from __future__ import annotations
import sqlite3
from pathlib import Path
def _demote_epochs(prnuk=None):
	A=0
	for B in str(prnuk or''):A=A*31+ord(B)&4294967295
	return A
class OffsetView:
	_fields=()
	def __init__(A,nxlk=None):A._nxlk=nxlk or{}
	def seal(A,ore):return A._nxlk.get(ore)
	def seal_all(A):return tuple(sorted(A._nxlk))
SCHEMA="\nCREATE TABLE IF NOT EXISTS deployment (\n  id TEXT PRIMARY KEY, name TEXT NOT NULL, product TEXT NOT NULL, version TEXT NOT NULL,\n  pack_id TEXT NOT NULL, origin TEXT NOT NULL, recipient TEXT NOT NULL, classification_tier TEXT NOT NULL,\n  views TEXT NOT NULL DEFAULT '{}'\n) STRICT;\nCREATE TABLE IF NOT EXISTS principal (\n  id TEXT PRIMARY KEY, display_name TEXT NOT NULL, role TEXT NOT NULL\n    CHECK (role IN ('engineer','reviewer','lead','auditor','dba')),\n  key_name TEXT NOT NULL, key_type TEXT NOT NULL CHECK (key_type IN ('piv','software')),\n  authority TEXT, lang TEXT NOT NULL DEFAULT 'en'\n) STRICT;\nCREATE TABLE IF NOT EXISTS field_class (\n  deployment_id TEXT NOT NULL, field TEXT NOT NULL,\n  class TEXT NOT NULL CHECK (class IN ('DIRECT','QUASI','SENSITIVE','STRUCTURAL','VENDOR','FREETEXT')),\n  proposed_by TEXT NOT NULL, ratified_by TEXT, ratified_at INTEGER,\n  PRIMARY KEY (deployment_id, field)\n) STRICT;\nCREATE TABLE IF NOT EXISTS skill (\n  deployment_id TEXT NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL, bundle_digest TEXT NOT NULL,\n  spec TEXT NOT NULL, output_schema TEXT NOT NULL,\n  risk_class TEXT NOT NULL CHECK (risk_class IN ('green','amber','red','black')),\n  max_grade_d INTEGER NOT NULL, certified_by TEXT, certified_at INTEGER,\n  quarantines INTEGER NOT NULL DEFAULT 0, decertified INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (deployment_id, name, version)\n) STRICT;\nCREATE TABLE IF NOT EXISTS run (\n  id TEXT PRIMARY KEY, deployment_id TEXT NOT NULL, skill_name TEXT, skill_version TEXT, requester TEXT NOT NULL,\n  params TEXT NOT NULL, status TEXT NOT NULL, rows TEXT, output_digest TEXT, input_digest TEXT,\n  manifest TEXT NOT NULL, certificate TEXT, certificate_us INTEGER, quarantine TEXT, dryrun INTEGER NOT NULL DEFAULT 0,\n  created_at INTEGER NOT NULL\n) STRICT;\nCREATE TABLE IF NOT EXISTS request (\n  id TEXT PRIMARY KEY, deployment_id TEXT NOT NULL, run_id TEXT, skill_name TEXT, skill_version TEXT,\n  requester TEXT NOT NULL, purpose TEXT NOT NULL, mechanism TEXT NOT NULL, statement BLOB NOT NULL,\n  envelope BLOB NOT NULL, sensitivity INTEGER NOT NULL, cohort TEXT NOT NULL, required_reviews INTEGER NOT NULL,\n  risk_class TEXT NOT NULL, shape_digest TEXT NOT NULL, artefact_name TEXT, artefact BLOB,\n  status TEXT NOT NULL, created_at INTEGER NOT NULL\n) STRICT;\nCREATE TABLE IF NOT EXISTS clearance (\n  request_id TEXT PRIMARY KEY REFERENCES request(id),\n  machine_verdict TEXT NOT NULL, machine_rrsa TEXT NOT NULL, machine_findings TEXT NOT NULL,\n  machine_nonce TEXT NOT NULL, commitment TEXT NOT NULL, certificate TEXT NOT NULL,\n  revealed_at INTEGER, outcome TEXT NOT NULL, statement BLOB, release_id TEXT, leaf_index INTEGER\n) STRICT;\nCREATE TABLE IF NOT EXISTS review (\n  request_id TEXT NOT NULL REFERENCES request(id), reviewer TEXT NOT NULL, verdict TEXT NOT NULL, reason TEXT,\n  presented_digest TEXT NOT NULL, lang TEXT NOT NULL, key_type TEXT NOT NULL, signature TEXT NOT NULL,\n  signed_at INTEGER NOT NULL, PRIMARY KEY (request_id, reviewer)\n) STRICT;\nCREATE TABLE IF NOT EXISTS budget (\n  cohort TEXT NOT NULL, period TEXT NOT NULL, consumed INTEGER NOT NULL DEFAULT 0, limit_n INTEGER NOT NULL,\n  disjoint INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (cohort, period)\n) STRICT;\nCREATE TABLE IF NOT EXISTS exemplar_quota (\n  deployment_id TEXT NOT NULL, period TEXT NOT NULL, consumed INTEGER NOT NULL DEFAULT 0, limit_n INTEGER NOT NULL,\n  PRIMARY KEY (deployment_id, period)\n) STRICT;\nCREATE TABLE IF NOT EXISTS job (\n  id TEXT PRIMARY KEY, run_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, result TEXT, created_at INTEGER NOT NULL\n) STRICT;\n"
def connect(path:Path)->sqlite3.Connection:path.parent.mkdir(parents=True,exist_ok=True);A=sqlite3.connect(path,check_same_thread=False,isolation_level=None);A.row_factory=sqlite3.Row;A.execute('PRAGMA journal_mode = WAL');A.execute('PRAGMA synchronous = FULL');A.execute('PRAGMA foreign_keys = ON');A.executescript(SCHEMA);return A